import{_ as e,o as r,a,b as o}from"./app.DKoEZOcr.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"同步控制","link":"/api/SIMD-API/basic_api/sync_control/sync_control"},{"text":"系统同步能力概述","link":"/api/SIMD-API/basic_api/sync_control/system_sync_overview"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/sync_control/system_sync_overview.md","filePath":"api/SIMD-API/basic_api/sync_control/system_sync_overview.md","lastUpdated":1787050286000}'),s={name:"api/SIMD-API/basic_api/sync_control/system_sync_overview.md"};function n(i,t,d,c,_,l){return r(),a("div",null,[...t[0]||(t[0]=[o('<div><article class="markdown-body"><h1>系统同步能力概述<span id="ZH-CN_TOPIC_0000002586323695"></span></h1><p>在编程中，同步是指协调多个执行单元（如线程、进程等）对共享资源的访问顺序和时机来确保程序的正确性。如果没有同步来严格控制执行顺序，则会出现结果不一致、行为不可预测等多种问题。</p><p>AI Core的同步，总共分成3类：核内同步、核间同步、任务间同步。各类同步对应的接口如下。</p><p><strong>表1</strong> 核内同步接口</p><table><thead><tr><th>接口名称</th><th>功能简述</th><th>同步类别</th></tr></thead><tbody><tr><td><a href="intra_core_sync/SetFlag_WaitFlag_ISASI.html">SetFlag/WaitFlag(ISASI)</a></td><td>多流水同步：同一核内不同流水之间的同步指令。SetFlag负责发送通知，WaitFlag负责阻塞直到SetFlag发送通知。</td><td>硬件同步</td></tr><tr><td><a href="intra_core_sync/PipeBarrier_ISASI.html">PipeBarrier</a></td><td>单流水同步：同一核内相同流水之间的同步指令（不支持PIPE_S单流水同步）。</td><td>硬件同步</td></tr><tr><td><a href="intra_core_sync/DataSyncBarrier_ISASI.html">DataSyncBarrier</a></td><td>阻塞后续的指令执行，直到所有之前的内存访问指令（需要等待的内存位置可通过参数控制）执行结束。</td><td>硬件同步</td></tr><tr><td><a href="intra_core_sync/Mutex_ISASI.html">Lock/Unlock</a></td><td>用于核内异步流水指令之间的同步处理，其功能类似于传统CPU中的锁机制。通过锁定指定流水再释放流水来完成流水间的同步依赖。</td><td>硬件同步</td></tr></tbody></table><p><strong>表2</strong> 核间同步接口</p><table><thead><tr><th>接口名称</th><th>功能简述</th><th>同步类别</th></tr></thead><tbody><tr><td><a href="inter_core_sync/CrossCoreSetFlag_ISASI.html">CrossCoreSetFlag</a>/<a href="inter_core_sync/CrossCoreWaitFlag_ISASI.html">CrossCoreWaitFlag</a></td><td>多个AIC或AIV之间的同步控制。CrossCoreSetFlag负责发送通知，CrossCoreWaitFlag负责阻塞直到CrossCoreSetFlag发送通知。<br>支持以下同步场景：<br>•同步等待全部AIC或者同步等待全部AIV执行结束。<br>•单个AI Core内，全部AIV之间的同步。<br>•单个AI Core内，AIC与全部AIV之间的同步。</td><td>硬件同步</td></tr><tr><td><a href="inter_core_sync/IBSet.html">IBSet</a>/<a href="inter_core_sync/IBWait.html">IBWait</a></td><td>被等待核中调用IBSet，通过将值1写入全局内存中某块地址来通知等待核；而等待核中调用IBWait，持续读取全局内存中相应地址块的值，直到其值变为1。</td><td>软件同步</td></tr><tr><td><a href="inter_core_sync/SyncAll.html">SyncAll</a></td><td>用于多个核之间的同步控制，支持以下同步场景：<br>•纯Vector算子的全核同步，可参考<a href="inter_core_sync/key_features.html">CrossCoreSetFlag的模式0</a>。<br>•融合算子的全核同步，一次性实现三个核间同步能力（参考<a href="inter_core_sync/key_features.html">CrossCoreSetFlag的关键特性说明</a>）：首先完成单个AI Core内，AIC与全部AIV之间的同步（AIC等AIV）；接着完成多个AI Core间，所有AIC的同步；最后完成单个AI Core内，所有AIV与AIC同步（AIV等AIC）。</td><td>硬件同步</td></tr><tr><td><a href="inter_core_sync/SyncAll.html">SyncAll</a></td><td>仅支持纯Vector算子的多核（参与同步的核数可通过入参指定）同步。每一个AIV都向全局内存对应位置写入信号值1，接着每一个AIV都持续轮询全局内存中所有AIV对应的信号值，直到所有AIV核对应的信号值都变为1。</td><td>软件同步</td></tr><tr><td><a href="inter_core_sync/InitDetermineComputeWorkspace.html">InitDetermineComputeWorkspace</a>/<a href="inter_core_sync/NotifyNextBlock.html">NotifyNextBlock</a>/<a href="inter_core_sync/WaitPreBlock.html">WaitPreBlock</a></td><td>• InitDetermineComputeWorkspace、NotifyNextBlock和WaitPreBlock三个接口必须组合使用，能够确保多个AIV核严格按照blockIdx的升序执行，适用于要求确定性计算的场景。<br>• InitDetermineComputeWorkspace初始化GM共享内存的值，完成初始化后才可以调用NotifyNextBlock和WaitPreBlock。<br>• NotifyNextBlock通过写全局内存来通知其他核当前核已执行完成，其他核可以继续往下执行；WaitPreBlock通过读取全局内存，判断当前核是否可以继续往下执行。</td><td>软件同步</td></tr></tbody></table><p><strong>表3</strong> 任务间同步接口</p><table><thead><tr><th>接口名称</th><th>功能简述</th><th>同步类别</th></tr></thead><tbody><tr><td><a href="./inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a></td><td>在SuperKernel的子核函数（Kernel）中调用，调用后的指令可以和后续其他的子核函数（Kernel）实现并行，提升整体性能。</td><td>硬件同步</td></tr><tr><td><a href="./inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a></td><td>在SuperKernel的子核函数（Kernel）中调用，调用前的指令可以和前序其他的子核函数（Kernel）实现并行，提升整体性能。</td><td>硬件同步</td></tr></tbody></table></article></div>',1)])])}const S=e(s,[["render",n]]);export{h as __pageData,S as default};
